import textwrap


def print_intent_tree(data, max_width=10000, is_show_response=False):
    # ManagerAgent
    print(f"{data.get('agent_name', 'ManagerAgent')}")
    # User Question
    print("└── User Question")
    question = data.get("user_question", "")
    wrapped_question = textwrap.wrap(question, width=max_width) or [""]
    for i, line in enumerate(wrapped_question):
        if i == 0:
            print(f"    └── {line}")
        else:
            print(f"        {line}")
    data_list = data.get("intent_s", [])
    for idx, item in enumerate(data_list, start=1):
        is_last_intent = (idx == len(data_list))
        intent_prefix = "        └──" if is_last_intent else "        ├──"
        intent_child_prefix = "            " if is_last_intent else "        │   "
        print(f"{intent_prefix} [{item['intent_type']}] {item['intent']}")
        tasks = item.get("task_s", [])
        for i, task in enumerate(tasks):
            is_last_task = (i == len(tasks) - 1)
            task_prefix = (
                f"{intent_child_prefix}└──"
                if is_last_task
                else f"{intent_child_prefix}├──"
            )
            child_prefix = (
                f"{intent_child_prefix}    "
                if is_last_task
                else f"{intent_child_prefix}│   "
            )
            print(f"{task_prefix} task_{i+1}[{task.get('agent_name', '')}]")
            """
            print(f"{child_prefix}├── agent_name")
            print(f"{child_prefix}│   └── {task.get('agent_name', '')}")
            """
            print(f"{child_prefix}├── task_description")
            desc_lines = textwrap.wrap(task.get("task_description", ""), width=max_width)
            for j, line in enumerate(desc_lines):
                connector = "└──" if j == 0 else "    "
                print(f"{child_prefix}   {connector} {line}")
            if is_show_response:
                print(f"{child_prefix}└── response")
                response = task.get("response", "")
                response_lines = response.split("\n")
                for line in response_lines:
                    wrapped = (
                        textwrap.wrap(line, width=max_width)
                        or [""]
                    )
                    for w in wrapped:
                        print(f"{child_prefix}    └── {w}")

